    /**
     * Returns the belongsTo film relation associated with inventory.film_id.
     *
     * Reads the inventory record, retrieves the foreign-key value, and resolves the label
     * configured through the generated Model.
     *
     * @param string $id Primary key of the inventory record.
     *
     * @return array{
     *     field: string,
     *     parentTable: string,
     *     value: string|null,
     *     relation: array<string,mixed>|null
     * }
     */
    #[McpTool(
        name: 'get_inventory_film_id',
        title: 'Get film relation for inventory.film_id'
    )]
    public function getInventoryFilmId(string $id): array
    {
        $record = $this->model->getDetail($id);
        if (!is_object($record)) {
            throw new \InvalidArgumentException('Record not found.');
        }
        $foreignId = is_array($record)
            ? ($record['film_id'] ?? null)
            : ($record->film_id ?? null);

        if ($foreignId === null || $foreignId === '') {
            return [
                'field' => 'film_id',
                'parentTable' => 'film',
                'value' => null,
                'relation' => null,
            ];
        }

        return [
            'field' => 'film_id',
            'parentTable' => 'film',
            'value' => (string) $foreignId,
            'relation' => $this->model->relationOptionById('film_id', $foreignId),
        ];
    }

